import java.io.BufferedInputStream
import java.util.PriorityQueue

private val vis = Array(110) { IntArray(110) }
private val directions = arrayOf(
    intArrayOf(0, 1),
    intArrayOf(1, 0),
    intArrayOf(0, -1),
    intArrayOf(-1, 0)
)

private data class Node(val x: Int, val y: Int, val step: Int)

private fun bfs(l: Int, u: Int, xi: Int, yi: Int): Int {
    val queue = PriorityQueue<Node>(compareBy { it.step })
    queue.offer(Node(l, u, 0))
    vis[l][u] = 1

    while (queue.isNotEmpty()) {
        val current = queue.poll()
        if (current.x == xi && current.y == yi) {
            return current.step
        }

        for (direction in directions) {
            val nx = current.x + direction[0]
            val ny = current.y + direction[1]
            val nextStep = current.step + 1

            if (nx < 0 || ny < 0) continue
            if (vis[nx][ny] != 0) continue

            vis[nx][ny] = 1
            queue.offer(Node(nx, ny, nextStep))
        }
    }

    return -1
}

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun next(): String {
        val result = StringBuilder()
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c != -1)

        while (c > 32 && c != -1) {
            result.append(c.toChar())
            c = readByte()
        }
        return result.toString()
    }
}

fun main() {
    val scanner = FastScanner()
    val s = scanner.next()
    val len = s.length

    var x = 0
    var y = 0
    var xx = 0
    var yy = 0

    for (c in s) {
        when (c) {
            'L' -> y--
            'R' -> y++
            'U' -> x--
            'D' -> x++
        }
        xx = minOf(xx, x)
        yy = minOf(yy, y)
    }

    xx = -xx
    yy = -yy

    for (i in 0 until 110) {
        for (j in 0 until 110) {
            vis[i][j] = 1
        }
    }

    x = xx
    y = yy

    for (c in s) {
        when (c) {
            'L' -> y--
            'R' -> y++
            'U' -> x--
            'D' -> x++
        }
        vis[x][y] = 0
    }

    val answer = bfs(xx, yy, x, y)
    if (answer == len) {
        print("OK\n")
    } else {
        print("BUG\n")
    }
}

